import os, re, json, csv, shutil

TEXT = json.load(open('/app/work/text.json'))
DOCS='/app/documents'; INV='/app/invoices'; OTH='/app/other'
os.makedirs(INV, exist_ok=True); os.makedirs(OTH, exist_ok=True)

def num(s):
    s = s.strip().replace(' ',' ').replace(' ','')
    if ',' in s and '.' in s:
        s = s.replace('.','').replace(',','.') if s.rfind(',')>s.rfind('.') else s.replace(',','')
    elif ',' in s:
        s = s.replace(',','.') if len(s.split(',')[-1])<=2 else s.replace(',','')
    return float(s)

MONEY = r'(\d[\d . ,]*\d|\d)'

def is_invoice(t):
    return re.search(r'\binvoice\b', t, re.I) is not None

def extract(t):
    # Northwind style
    m = re.search(r'Total\s*Price\s*:?\s*\n?\s*\$?\s*'+MONEY, t, re.I)
    if m and re.search(r'TotalPrice|Total Price', t, re.I):
        total = num(m.group(1)); vat = 0.0
        mv = re.search(r'(?:VAT|GST)[^\n\d]*'+MONEY, t, re.I)
        if mv: vat = num(mv.group(1))
        return total, vat
    # Tabular summary style (Net worth / VAT / Gross worth)
    if re.search(r'gross\s*worth', t, re.I) and re.search(r'\bVAT\b', t, re.I):
        vals = [num(x) for x in re.findall(r'\$\s*'+MONEY, t)]
        if len(vals) >= 3:
            net, vat, gross = vals[-3], vals[-2], vals[-1]
            return gross, vat
    # Generic: prefer "Total" over "Amount Due"
    total = vat = None
    for pat in [r'Grand\s*Total\s*:?\s*\$?\s*'+MONEY, r'\bTotal\s*:?\s*\$?\s*'+MONEY,
                r'Amount\s*[Dd]ue\s*:?\s*\$?\s*'+MONEY]:
        m = re.search(pat, t, re.I)
        if m:
            total = num(m.group(1)); break
    mv = re.search(r'(?:\bVAT\b|\bTax\b|\bGST\b)(?!\s*Id)[^\n\d%]*\$?\s*'+MONEY, t, re.I)
    if mv: vat = num(mv.group(1))
    return (total if total is not None else 0.0), (vat if vat is not None else 0.0)

rows=[]
for fn in sorted(TEXT):
    t = TEXT[fn]
    src = os.path.join(DOCS, fn)
    if is_invoice(t):
        shutil.move(src, os.path.join(INV, fn))
        total, vat = extract(t)
        rows.append([fn, f'{total:.2f}', f'{vat:.2f}'])
    else:
        shutil.move(src, os.path.join(OTH, fn))

st = sum(float(r[1]) for r in rows); sv = sum(float(r[2]) for r in rows)
