import os, re, csv, glob, shutil
import fitz, pytesseract
from PIL import Image

DOCS='/app/documents'; INV='/app/invoices'; OTH='/app/other'
for d in (INV,OTH): os.makedirs(d, exist_ok=True)

def layout_text(img):
    """Reconstruct reading-order lines from word boxes (public pytesseract API)."""
    d = pytesseract.image_to_data(img, output_type=pytesseract.Output.DICT)
    rows = {}
    for i, txt in enumerate(d['text']):
        if not txt.strip(): continue
        yc = d['top'][i] + d['height'][i] / 2
        key = min(rows, key=lambda k: abs(k - yc), default=None)
        if key is None or abs(key - yc) > d['height'][i] * 0.6:
            key = yc; rows[key] = []
        rows[key].append((d['left'][i], txt))
    return '\n'.join(' '.join(t for _, t in sorted(rows[k])) for k in sorted(rows))

def doc_text(path):
    if path.lower().endswith('.pdf'):
        with fitz.open(path) as doc:
            t = '\n'.join(p.get_text() for p in doc)
            if len(t.strip()) >= 20:
                return t
            out = []
            for p in doc:
                pix = p.get_pixmap(dpi=300)
                out.append(layout_text(Image.frombytes('RGB', [pix.width, pix.height], pix.samples)))
            return '\n'.join(out)
    return layout_text(Image.open(path))

def num(s):
    s = re.sub(r'[\s ]', '', s)
    if ',' in s and '.' in s:
        s = s.replace('.', '').replace(',', '.') if s.rfind(',') > s.rfind('.') else s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.') if len(s.split(',')[-1]) <= 2 else s.replace(',', '')
    return float(s)

MONEY = r'(\d[\d\s.,]*\d|\d)'

def is_invoice(t):
    return re.search(r'\binvoice\b', t, re.I) is not None

def extract(t):
    # 1) "Total Price" / "TotalPrice" layouts
    if re.search(r'Total\s*Price', t, re.I):
        m = re.search(r'Total\s*Price\s*:?\s*\n?\s*\$?\s*' + MONEY, t, re.I)
        if m:
            mv = re.search(r'(?:\bVAT\b|\bGST\b|\bTax\b)(?!\s*Id)[^\n\d%]*\$?\s*' + MONEY, t, re.I)
            return num(m.group(1)), (num(mv.group(1)) if mv else 0.0)
    # 2) Tabular summary: Net worth | VAT | Gross worth
    if re.search(r'gross\s*worth', t, re.I) and re.search(r'\bVAT\b', t, re.I):
        vals = [num(x) for x in re.findall(r'\$\s*' + MONEY, t)]
        if len(vals) >= 3:
            return vals[-1], vals[-2]
    # 3) Generic labels; "Total" wins over "Amount Due"
    total = 0.0
    for pat in (r'Grand\s*Total\s*:?\s*\$?\s*' + MONEY,
                r'(?<!Sub)(?<!Sub )\bTotal\b\s*:?\s*\$?\s*' + MONEY,
                r'Amount\s*Due\s*:?\s*\$?\s*' + MONEY):
        m = re.search(pat, t, re.I)
        if m:
            total = num(m.group(1)); break
    mv = re.search(r'(?:\bVAT\b|\bGST\b|\bTax\b)(?!\s*Id)[^\n\d%]*\$?\s*' + MONEY, t, re.I)
    return total, (num(mv.group(1)) if mv else 0.0)

rows = []
for path in sorted(glob.glob(os.path.join(DOCS, '*'))):
    fn = os.path.basename(path)
    t = doc_text(path)
    if is_invoice(t):
        total, vat = extract(t)
        rows.append([fn, f'{total:.2f}', f'{vat:.2f}'])
        shutil.move(path, os.path.join(INV, fn))
    else:
        shutil.move(path, os.path.join(OTH, fn))

rows.append(['total', f'{sum(float(r[1]) for r in rows):.2f}', f'{sum(float(r[2]) for r in rows):.2f}'])
with open(os.path.join(INV, 'summary.csv'), 'w', newline='') as f:
    w = csv.writer(f); w.writerow(['filename', 'total_amount', 'vat_amount']); w.writerows(rows)
print(open(os.path.join(INV, 'summary.csv')).read())
